  x = (Math.imul(x, A) + C) & MASK; // (x*A + C) mod 2^31, 精度见 gencheck.js
  if (size < K) {
    let c = size++;
    heap[c] = x;
    while (c > 0) {
      const p = (c - 1) >> 1;
      if (heap[p] <= heap[c]) break;
      const t = heap[p]; heap[p] = heap[c]; heap[c] = t;
      c = p;
    }
  } else if (x > heap[0]) {
