function probe(url){
  return new Promise(resolve => {
    let done = false;
    const timer = setTimeout(() => { if(!done){ done = true; try{req.destroy();}catch(e){} resolve({url, status:0, err:'timeout after 20s'}); } }, 20000);
    const req = https.get(url, { headers: { 'user-agent': 'node-probe' } }, res => {
      let d = '';
      res.on('data', c => d += c);
      res.on('end', () => {
        if (done) return; done = true; clearTimeout(timer);
        resolve({ url, status: res.statusCode, len: d.length, hasTHREE: d.indexOf('THREE') !== -1,
                  rev: (d.match(/REVISION\s*=\s*["']([^"']+)["']/) || [])[1] || null });
      });
    });
    req.on('error', e => { if (done) return; done = true; clearTimeout(timer); resolve({ url, status: 0, err: e.message }); });
  });
}

function findBrowser(){
  const cands = [
    process.env.LOCALAPPDATA && path.join(process.env.LOCALAPPDATA, 'Google\\Chrome\\Application\\chrome.exe'),
    'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',
    'C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe',
    'C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe',
    'C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe',
    process.env.PROGRAMFILES && path.join(process.env.PROGRAMFILES, 'Microsoft\\Edge\\Application\\msedge.exe')
  ].filter(Boolean);
  for (const c of cands) { if (fs.existsSync(c)) return c; }
  return null;
}

function runBrowser(exe, flags, url, ms){
  return new Promise(resolve => {
    const child = spawn(exe, flags.concat([url]), { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '', err = '';
    child.stdout.on('data', d => out += d);
    child.stderr.on('data', d => err += d);
    const t = setTimeout(() => { try { child.kill(); } catch (e) {} }, ms);
    child.on('close', code => { clearTimeout(t); resolve({ code, out, err }); });
    child.on('error', e => { clearTimeout(t); resolve({ code: -1, out, err: err + '\nspawn error: ' + e.message }); });
  });
}

function extract(html){
  const i = html.indexOf('__SELFCHECK_JSON__');
  if (i === -1) return null;
  const j = html.indexOf('__END__', i);
  if (j === -1) return null;
  return html.slice(i + '__SELFCHECK_JSON__'.length, j);
}

