function probe(url) {
  return new Promise((resolve) => {
    const req = https.get(url, { timeout: 12000 }, (res) => {
      let body = '';
      res.setEncoding('utf8');
      res.on('data', (d) => { if (body.length < 3000000) body += d; });
      res.on('end', () => resolve({ url, status: res.statusCode, bytes: body.length, hasRev: /REVISION\s*=\s*["']128["']/.test(body) }));
    });
    req.on('timeout', () => { req.destroy(); resolve({ url, status: 'timeout', bytes: 0, hasRev: false }); });
    req.on('error', (e) => resolve({ url, status: 'error: ' + e.message, bytes: 0, hasRev: false }));
  });
}

function findBrowsers() {
  const cands = [];
  ['PROGRAMFILES', 'PROGRAMFILES(X86)', 'LOCALAPPDATA'].forEach((k) => {
    const base = process.env[k];
    if (!base) return;
    cands.push(path.join(base, 'Google', 'Chrome', 'Application', 'chrome.exe'));
    cands.push(path.join(base, 'Microsoft', 'Edge', 'Application', 'msedge.exe'));
  });
  ['chrome', 'msedge', 'chrome.exe'].forEach((cmd) => {
    const r = spawnSync('where', [cmd], { encoding: 'utf8' });
    if (r.status === 0) r.stdout.split(/\r?\n/).forEach((p) => { if (p.trim()) cands.push(p.trim()); });
  });
  const seen = new Set();
  return cands.filter((p) => { if (seen.has(p)) return false; seen.add(p); return fs.existsSync(p); });
}

function runBrowser(bin, args, timeoutMs) {
  return new Promise((resolve) => {
    let out = '', err = '', done = false;
    const p = spawn(bin, args, { windowsHide: true });
    const timer = setTimeout(() => { try { p.kill(); } catch (e) {} }, timeoutMs);
    p.stdout.on('data', (d) => { out += d.toString('utf8'); });
    p.stderr.on('data', (d) => { err += d.toString('utf8'); });
    p.on('error', (e) => { if (done) return; done = true; clearTimeout(timer); resolve({ code: -1, out, err: err + '\nspawn error: ' + e.message }); });
    p.on('close', (code) => { if (done) return; done = true; clearTimeout(timer); resolve({ code, out, err }); });
  });
}

