// ---------- 定位声明（保留签名原文） ----------
function findDecl(code, name) {
  const pats = [
    new RegExp('function\\s+' + name + '\\s*\\(([^)]*)\\)'),
    new RegExp('(?:module\\.)?exports\\.' + name + '\\s*=\\s*function\\s*\\(([^)]*)\\)'),
    new RegExp('(?:const|let|var)\\s+' + name + '\\s*=\\s*function\\s*\\(([^)]*)\\)'),
    new RegExp('(?:const|let|var)\\s+' + name + '\\s*=\\s*\\(([^)]*)\\)\\s*=>'),
    new RegExp('(?:const|let|var)\\s+' + name + '\\s*=\\s*([A-Za-z_$][\\w$]*)\\s*=>'),
  ];
  for (const p of pats) {
    const m = p.exec(code);
    if (m) return { index: m.index, end: m.index + m[0].length, params: m[1] };
  }
  return null;
}

function scanBlock(code, start) { // start 指向 '{'
  let i = start, depth = 0, st = null;
  for (; i < code.length; i++) {
    const c = code[i], n = code[i + 1];
    if (st === 'line') { if (c === '\n') st = null; continue; }
    if (st === 'block') { if (c === '*' && n === '/') { st = null; i++; } continue; }
    if (st) { if (c === '\\') { i++; continue; }
      if ((st === 'sq' && c === "'") || (st === 'dq' && c === '"') || (st === 'tpl' && c === '`')) st = null; continue; }
    if (c === '/' && n === '/') { st = 'line'; i++; continue; }
    if (c === '/' && n === '*') { st = 'block'; i++; continue; }
    if (c === "'") { st = 'sq'; continue; }
    if (c === '"') { st = 'dq'; continue; }
    if (c === '`') { st = 'tpl'; continue; }
    if (c === '{') depth++;
    else if (c === '}') { depth--; if (depth === 0) return [start, i]; }
  }
  return null;
}

function scanExprEnd(code, start) { // 顶层 ';' 或换行结束
  let i = start, depth = 0, st = null;
  for (; i < code.length; i++) {
    const c = code[i], n = code[i + 1];
    if (st === 'line') { if (c === '\n') st = null; continue; }
    if (st === 'block') { if (c === '*' && n === '/') { st = null; i++; } continue; }
    if (st) { if (c === '\\') { i++; continue; }
      if ((st === 'sq' && c === "'") || (st === 'dq' && c === '"') || (st === 'tpl' && c === '`')) st = null; continue; }
    if (c === '/' && n === '/') { st = 'line'; i++; continue; }
    if (c === '/' && n === '*') { st = 'block'; i++; continue; }
    if (c === "'") { st = 'sq'; continue; }
    if (c === '"') { st = 'dq'; continue; }
    if (c === '`') { st = 'tpl'; continue; }
    if ('([{'.includes(c)) depth++;
    else if (')]}'.includes(c)) depth--;
    else if (c === ';' && depth === 0) return i;
    else if (c === '\n' && depth === 0) return i;
  }
  return i;
}

function patch(code, name, makeBody, report) {
  const d = findDecl(code, name);
  if (!d) { report.push('!! 未定位到 ' + name + ' 的声明'); return code; }
  const sig = code.slice(d.index, d.end);
  let i = d.end;
  while (i < code.length && /\s/.test(code[i])) i++;
  const pname = (d.params || '').trim().split(/[\s,=]/)[0] || 'xs';
  if (code[i] === '{') {
    const blk = scanBlock(code, i);
    if (!blk) { report.push('!! ' + name + ' 函数体括号不匹配'); return code; }
    if (name === 'mean') report.push('[真实根因-mean] 原函数体: ' + code.slice(blk[0], blk[1] + 1).replace(/\s+/g, ' ').slice(0, 200));
    if (name === 'p95') report.push('[真实根因-p95 ] 原函数体: ' + code.slice(blk[0], blk[1] + 1).replace(/\s+/g, ' ').slice(0, 200));
    const nb = makeBody(pname);
    report.push('[' + name + '] 保留签名: ' + sig);
    return code.slice(0, blk[0]) + nb + code.slice(blk[1] + 1);
  }
  const e = scanExprEnd(code, i);
  report.push('[' + name + '] 原表达式体: ' + code.slice(i, e).trim());
  report.push('[' + name + '] 保留签名: ' + sig);
  return code.slice(0, i) + makeBody(pname) + code.slice(e);
}

